ODSEK = "\\n### STOPNJA 1.6 — WITH LOVE / S LJUBEZNIJO ⊙ ⟨strojni-dih⟩ ⚠ ( ista objava §0.47: ni neodvisno preverjen )\\n\\n"
posod = 0
for sklop in (M1, M2, M3, M4):
    for kod, (naslov, telo) in sklop.items():
        pot = f'LICENSE-{kod}.md'
        if not os.path.exists(pot): print('× MANJKA:', pot); continue
        t = open(pot, encoding='utf-8', newline='').read()
        if 'STOPNJA 1.6' in t: continue
        with open(pot, 'a', encoding='utf-8', newline='') as f:
            f.write(ODSEK + f'**{naslov}**\\n\\n{telo}\\n')
        posod += 1
print(f'STOPNJA 1.6 ⊢ {posod}/36 stopnk prejelo WITH LOVE ( pozdrav vrat ) · destinacija ⭢ stopnja 2.0 ( celotna vrata, en jezik na dih ⊙ kalibracija Zip 8.3 )')
